private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principalObj,
                                                Object credentialsObj) throws NamingException {
    // Validate input parameters early to avoid ambiguous failures later
    if (principalObj == null || credentialsObj == null) {
        throw new IllegalArgumentException("Principal and credentials must not be null");
    }
    final String principal = principalObj.toString();
    final String credentials = credentialsObj.toString();

    // Cast the factory to the concrete type we expect
    final JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;

    // Build the initial environment – no credentials yet so that the connection is made anonymously
    final Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiFactory.getUrl());
    // Use the configured authentication mechanism (e.g., SIMPLE, DIGEST-MD5)
    env.put(Context.SECURITY_AUTHENTICATION, jndiFactory.getAuthenticationMechanism());

    LdapContext ctx = null;
    try {
        // Create the context without credentials – this will succeed even if the user is not yet authenticated
        ctx = new InitialLdapContext(env, null);

        // Negotiate STARTTLS before any authentication takes place
        final StartTlsRequest tlsReq = new StartTlsRequest();
        final StartTlsResponse tlsResp = (StartTlsResponse) ctx.extendedOperation(tlsReq);
        tlsResp.negotiate(); // throws IOException on failure

        // Re‑authenticate over the secured channel
        final Hashtable<String, Object> authEnv = new Hashtable<>(env);
        authEnv.put(Context.SECURITY_PRINCIPAL, principal);
        authEnv.put(Context.SECURITY_CREDENTIALS, credentials);
        ctx.reconnect(authEnv); // throws AuthenticationException if credentials are invalid

        // At this point the context is authenticated and TLS is negotiated
        return ctx;
    } catch (AuthenticationException ae) {
        // Authentication failed – close the context and surface a clear error
        LdapUtils.closeContext(ctx);
        securityLog.warn(withRealm("Authentication failed for user '%s' against '%s': %s",
                principal, server(jndiFactory), ae.getMessage()));
        throw ae;
    } catch (IOException ioe) {
        // TLS negotiation failed – close the context and surface a clear error
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                server(jndiFactory), ioe.getMessage()), ioe);
        throw new CommunicationException(ioe.getMessage(), ioe);
    } catch (NamingException ne) {
        // Any other naming-related failure – propagate after cleanup
        LdapUtils.closeContext(ctx);
        throw ne;
    } catch (Throwable t) {
        // Unexpected failure – ensure resources are released
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Unexpected failure to establish LDAP connection with '%s': %s",
                server(jndiFactory), t.getMessage()), t);
        throw t;
    }
}
