     * @param version   the full version string (for error messages)
     * @return the parsed integer value
     * @throws IllegalArgumentException if the component cannot be parsed as an integer
     */
    private static int parseComponent(String part, String component, String version) {
        try {
            return Integer.parseInt(part);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                    String.format("Invalid %s component '%s' in version '%s'", component, part, version),
                    e);
        }
    }

