public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                    */
    /* --------------------------------------------------------------------- */

    /** Packages that are considered safe for deserialization. */
    private static final Set<String> SAFE_PACKAGE_PREFIXES =
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "java.lang.",
                    "java.math.",
                    "java.util.",
                    "java.time.",
                    "java.sql."
            )));

    /**
     * Checks whether a given class is allowed to be used as a component type.
     *
     * @param cls the class to check
     * @return {@code true} if the class is in a safe package or is a primitive
     */
    private static boolean isAllowedComponentClass(Class<?> cls) {
        if (cls == null) {
            return false;
        }
        if (cls.isPrimitive()) {
            return true;
        }
        String pkg = cls.getPackage() != null ? cls.getPackage().getName() : "";
        for (String prefix : SAFE_PACKAGE_PREFIXES) {
            if (pkg.startsWith(prefix)) {
                return true;
            }
        }
        return false;
    }

