@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while protecting
     * against XML External Entity (XXE) attacks. The method explicitly disables
     * external entity resolution, DTD loading, and DOCTYPE declarations on both
     * the {@link SAXParserFactory} and the resulting {@link XMLReader}. If the
     * parser cannot be created, a {@link SAXException} is thrown.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange used to retrieve a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be instantiated or configured
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // General security features
            enableFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            enableFeature(sfactory, "http://xml.org/sax/features/external-general-entities", false);
            enableFeature(sfactory, "http://xml.org/sax/features/external-parameter-entities", false);
            enableFeature(sfactory, "http://apache.org/xml/features/disallow-doctype-decl", true);

            // Disable validation and XInclude to reduce attack surface
            sfactory.setNamespaceAware(true);
            sfactory.setValidating(false);
            sfactory.setXIncludeAware(false);

